const path = require('path');
require('dotenv').config({ path: path.resolve(__dirname, '..', '.env') });
const mongoose = require('mongoose');

const SCHOOL_ID = new mongoose.Types.ObjectId('69ce960a98ca4ee738d25416');
const CREATED_BY = new mongoose.Types.ObjectId('69ce960b98ca4ee738d25432');

let blockNum = 0;
function bid() { return 'block-' + String(++blockNum).padStart(3, '0'); }

function t(order, content) {
  return { blockId: bid(), type: 'text', order, content, points: 0, hints: [], explanation: '', metadata: {}, curriculumNodeId: null, cognitiveLevel: null };
}
function q(order, question, options, correctIndex, explanation, hints) {
  return {
    blockId: bid(), type: 'quiz', order,
    content: JSON.stringify({ question, options, correctIndex }),
    points: 1, hints: hints || [], explanation: explanation || '',
    metadata: { options, correctIndex }, curriculumNodeId: null, cognitiveLevel: null,
  };
}
function fb(order, text, blanks, explanation, hints) {
  return {
    blockId: bid(), type: 'fill_blank', order,
    content: JSON.stringify({ text, blanks }),
    points: blanks.length, hints: hints || [], explanation: explanation || '',
    metadata: { blanks }, curriculumNodeId: null, cognitiveLevel: null,
  };
}

// =============================================================================
// CHAPTER 1 (History – Term 1): Democracy and Human Rights in South Africa
// =============================================================================

// --- Lesson 1: The Road to Democracy ---
blockNum = 0;
const ch1_lesson1 = [
  t(1, '## What Is Democracy?\n\nThe word **democracy** comes from the Greek words *demos* (people) and *kratos* (rule). Democracy means **rule by the people**.\n\nIn a democracy:\n- Citizens have the right to **vote** for their leaders\n- The government is chosen by the **majority** of voters\n- All people are treated **equally** before the law\n- People have **rights and freedoms** that are protected\n\n### Types of Democracy\n\n| Type | How It Works | Example |\n|------|-------------|----------|\n| **Direct democracy** | Citizens vote on every issue themselves | Ancient Athens |\n| **Representative democracy** | Citizens elect representatives to make decisions for them | South Africa today |\n\nSouth Africa is a **representative democracy** — we vote for political parties, and those parties send representatives to Parliament to make laws on our behalf.'),
  q(2, 'What type of democracy does South Africa have?',
    ['A representative democracy where citizens elect representatives to make decisions', 'A direct democracy where citizens vote on every issue', 'A monarchy where the king makes all decisions', 'An autocracy where one person rules'], 0,
    'South Africa is a representative democracy. Citizens vote for political parties during elections, and those parties send Members of Parliament to represent the people and make laws.'),
  t(3, '## Apartheid in South Africa\n\n**Apartheid** was a system of racial segregation enforced by the National Party government from **1948 to 1994**. The word *apartheid* is an Afrikaans word meaning **"separateness"**.\n\n### Key Apartheid Laws\n\n| Law | What It Did |\n|-----|-------------|\n| **Population Registration Act (1950)** | Classified every person by race: White, Coloured, Indian, or African |\n| **Group Areas Act (1950)** | Forced different racial groups to live in separate areas |\n| **Bantu Education Act (1953)** | Gave black South Africans inferior education designed to prepare them for manual labour |\n| **Pass Laws** | Required black South Africans to carry a passbook (dompas) at all times |\n| **Separate Amenities Act (1953)** | Separated public facilities — beaches, buses, benches, hospitals — by race |\n\n### Effects of Apartheid\n\n- Black South Africans could **not vote** in national elections\n- Families were **forcibly removed** from their homes (e.g., District Six in Cape Town, Sophiatown in Johannesburg)\n- Education, healthcare, and services for black people were **deliberately inferior**\n- People who opposed apartheid were **arrested, banned, or killed**'),
  fb(4, 'Apartheid is an Afrikaans word meaning ___. The Population Registration Act of 1950 classified every person by ___.',
    ['separateness', 'race'],
    'Apartheid literally means "separateness" or "apart-hood." The Population Registration Act was one of the foundation laws of apartheid — it forced every South African to be classified into a racial group, which then determined where they could live, work, and go to school.'),
  t(5, '## Resistance to Apartheid\n\nSouth Africans fought against apartheid in many ways.\n\n### Key Resistance Events\n\n| Date | Event |\n|------|-------|\n| **1952** | The **Defiance Campaign** — people deliberately broke unjust apartheid laws |\n| **1955** | The **Congress of the People** adopted the **Freedom Charter**, which called for equal rights for all |\n| **1960** | The **Sharpeville Massacre** — police shot and killed 69 peaceful protesters |\n| **1960** | The ANC and PAC were **banned**; leaders went underground or into exile |\n| **1964** | **Nelson Mandela** and other leaders were sentenced to life imprisonment at the **Rivonia Trial** |\n| **1976** | The **Soweto Uprising** — students protested against being taught in Afrikaans; police killed Hector Pieterson and many others |\n| **1980s** | Mass protests, boycotts, and international **sanctions** put pressure on the apartheid government |\n\n### Key Figures in the Struggle\n\n- **Nelson Mandela** — leader of the ANC, imprisoned for 27 years\n- **Walter Sisulu** — ANC leader imprisoned with Mandela\n- **Albertina Sisulu** — activist who kept the struggle alive while leaders were in prison\n- **Desmond Tutu** — Archbishop who won the Nobel Peace Prize for peaceful opposition to apartheid\n- **Steve Biko** — leader of the Black Consciousness Movement, killed in police detention in 1977'),
  q(6, 'What was the Freedom Charter?',
    ['A document adopted in 1955 that called for equal rights for all South Africans regardless of race', 'The apartheid government\'s constitution', 'A law that banned the ANC', 'A trade agreement with other African countries'], 0,
    'The Freedom Charter was adopted at the Congress of the People in Kliptown, Soweto, on 26 June 1955. It declared that "South Africa belongs to all who live in it, black and white" and called for equal rights, land reform, and shared wealth. It became the foundation of South Africa\'s democratic Constitution.'),
  t(7, '## The End of Apartheid and the 1994 Elections\n\n### How Apartheid Ended\n\n- In **1990**, President **F.W. de Klerk** unbanned the ANC, PAC, and other organisations\n- **Nelson Mandela** was released from prison on **11 February 1990** after 27 years\n- **Negotiations** (called CODESA — Convention for a Democratic South Africa) began between the government and liberation movements\n- An **interim Constitution** was agreed upon\n- South Africa\'s **first democratic election** was held on **27 April 1994**\n\n### The 1994 Election\n\n| Fact | Detail |\n|------|--------|\n| **Date** | 27 April 1994 |\n| **Significance** | First time ALL South Africans could vote, regardless of race |\n| **Voter turnout** | Nearly 20 million people voted |\n| **Winner** | The **ANC** won with 62.6% of the vote |\n| **President** | **Nelson Mandela** became South Africa\'s first democratically elected president |\n| **Deputy Presidents** | Thabo Mbeki (ANC) and F.W. de Klerk (NP) |\n| **Government** | Government of National Unity — parties worked together |\n\n27 April is now celebrated as **Freedom Day** — a public holiday in South Africa.'),
  fb(8, 'Nelson Mandela was released from prison on 11 February ___. South Africa\'s first democratic election was held on 27 April ___.',
    ['1990', '1994'],
    'Mandela spent 27 years in prison, mostly on Robben Island. His release in 1990 was a turning point that led to negotiations and eventually the first democratic election in 1994, when all South Africans could vote for the first time.'),
  q(9, 'Why is 27 April celebrated as Freedom Day in South Africa?',
    ['It was the date of South Africa\'s first democratic election in 1994 when all citizens could vote regardless of race', 'It was the day Nelson Mandela was released from prison', 'It was the day apartheid laws were first introduced', 'It was the day the Freedom Charter was signed'], 0,
    'Freedom Day commemorates 27 April 1994 — the first time in South Africa\'s history that every adult citizen, regardless of race, could vote. It marks the birth of South Africa\'s democracy and the end of apartheid.'),
  t(10, '## South Africa\'s Government of National Unity\n\nAfter the 1994 election, South Africa formed a **Government of National Unity (GNU)**. This was a special arrangement where different political parties worked together to govern the country during the transition from apartheid to democracy.\n\n### Why a Government of National Unity?\n\n- To ensure **peace** during the transition — all groups had a voice\n- To prevent **revenge** and promote **reconciliation** (bringing people together)\n- To show the world that South Africa could change **peacefully**\n\n### The Truth and Reconciliation Commission (TRC)\n\n- Chaired by Archbishop **Desmond Tutu**\n- People who committed human rights abuses during apartheid could apply for **amnesty** (forgiveness) if they told the full truth\n- Victims could tell their stories and be heard\n- The TRC aimed to uncover the truth and promote **healing** rather than punishment\n- It was based on the African concept of **ubuntu** — "I am because we are"\n\nSouth Africa\'s peaceful transition from apartheid to democracy is seen as one of the greatest achievements in modern history.'),
];

// --- Lesson 2: The Constitution, Bill of Rights, and Citizenship ---
blockNum = 0;
const ch1_lesson2 = [
  t(1, '## The South African Constitution\n\nThe **Constitution of South Africa** was adopted on **10 December 1996** and came into effect on **4 February 1997**. It is the **supreme law** of the country — no other law or action may go against it.\n\n### Key Features of the Constitution\n\n| Feature | Explanation |\n|---------|-------------|\n| **Supreme law** | The Constitution is the highest law — all other laws must obey it |\n| **Bill of Rights** | Chapter 2 protects the rights of all people in South Africa |\n| **Constitutional Court** | The highest court, which decides if laws are constitutional |\n| **Three branches of government** | Legislature (makes laws), Executive (carries out laws), Judiciary (interprets laws) |\n| **Three spheres of government** | National, Provincial, and Local |\n| **Independent institutions** | The Public Protector, Human Rights Commission, and others protect democracy |\n\n### The Three Branches of Government\n\n- **Legislature (Parliament)**: Makes laws. Includes the National Assembly and the National Council of Provinces\n- **Executive (President and Cabinet)**: Carries out the laws and runs the country day to day\n- **Judiciary (Courts)**: Interprets the laws and settles disputes. The Constitutional Court is the highest court'),
  q(2, 'Why is the Constitution called the "supreme law" of South Africa?',
    ['Because no other law or government action may go against what the Constitution says', 'Because the President wrote it personally', 'Because it is the oldest law in South Africa', 'Because only judges can read it'], 0,
    'The Constitution is supreme because it is above all other laws. If any law or government action contradicts the Constitution, the Constitutional Court can declare it invalid. This protects the rights of all citizens.'),
  t(3, '## The Bill of Rights\n\nThe **Bill of Rights** is Chapter 2 of the Constitution. It lists the **fundamental rights** that every person in South Africa is entitled to.\n\n### Key Rights in the Bill of Rights\n\n| Right | What It Means |\n|-------|---------------|\n| **Equality (Section 9)** | Everyone is equal before the law and may not be unfairly discriminated against |\n| **Human dignity (Section 10)** | Everyone has the right to have their dignity respected and protected |\n| **Life (Section 11)** | Everyone has the right to life |\n| **Freedom and security (Section 12)** | No one may be tortured or treated in a cruel way |\n| **Education (Section 29)** | Everyone has the right to basic education |\n| **Healthcare, food, water (Section 27)** | Everyone has the right to access healthcare, food, water, and social security |\n| **Housing (Section 26)** | Everyone has the right to access adequate housing |\n| **Children\'s rights (Section 28)** | Children have the right to be protected from abuse, neglect, and exploitation |\n| **Environment (Section 24)** | Everyone has the right to an environment that is not harmful to health |\n\n### Rights Come with Responsibilities\n\nFor every right, there is a **responsibility**:\n- The right to **education** comes with the responsibility to **attend school and work hard**\n- The right to **freedom of expression** comes with the responsibility **not to spread hate speech**\n- The right to a **clean environment** comes with the responsibility to **not litter or pollute**'),
  fb(4, 'The Bill of Rights is found in Chapter ___ of the South African Constitution. Section 29 guarantees every person the right to basic ___.',
    ['2', 'education'],
    'Chapter 2 of the Constitution contains the Bill of Rights, which protects the fundamental rights of all people in South Africa. The right to basic education in Section 29 is especially important because education empowers people to improve their lives and participate fully in democracy.'),
  t(5, '## What Does It Mean to Be a Good Citizen?\n\nA **citizen** is a person who belongs to a country and has both **rights** and **responsibilities**.\n\n### Rights vs Responsibilities\n\n| Rights (What You Receive) | Responsibilities (What You Give) |\n|--------------------------|----------------------------------|\n| The right to vote | The responsibility to vote in elections |\n| The right to education | The responsibility to attend school and study |\n| The right to a safe environment | The responsibility to look after the environment |\n| The right to equality | The responsibility to treat others with respect |\n| The right to freedom of speech | The responsibility not to use hate speech |\n| The right to healthcare | The responsibility to look after your own health |\n\n### Being an Active Citizen\n\nGood citizens don\'t just enjoy their rights — they **actively contribute** to their communities:\n\n- **Obeying the law** — following the rules that keep everyone safe\n- **Paying taxes** — contributing money so the government can provide services\n- **Voting** — choosing leaders who will serve the people\n- **Volunteering** — helping in your community (cleaning up, tutoring, helping the elderly)\n- **Respecting diversity** — treating people of all races, religions, and cultures with respect\n- **Reporting crime** — helping to keep your community safe'),
  q(6, 'Which of the following is a responsibility that comes with the right to vote?',
    ['The responsibility to actually go and vote in elections so that your voice is heard', 'The responsibility to vote for the winning party only', 'The responsibility to tell others how to vote', 'There are no responsibilities — only rights matter'], 0,
    'In a democracy, voting is both a right and a responsibility. If citizens do not vote, they cannot hold the government accountable. Many South Africans fought and died for the right to vote, so exercising that right is a way of honouring their sacrifice.'),
  t(7, '## Symbols of South African Democracy\n\nSouth Africa\'s democracy is represented by important **national symbols** that reflect the country\'s diversity and unity.\n\n### National Symbols\n\n| Symbol | Significance |\n|--------|-------------|\n| **National flag** | The six colours represent the coming together of different groups into one united nation |\n| **National anthem** | Combines parts of *Nkosi Sikelel\' iAfrika* and *Die Stem van Suid-Afrika* in five of the eleven official languages |\n| **Coat of arms** | Features a protea, elephant tusks, ears of wheat, a secretary bird, and the motto *!ke e: /xarra //ke* ("Diverse People Unite") |\n| **Constitution** | The supreme law that protects the rights of all |\n\n### Public Holidays That Celebrate Democracy\n\n| Holiday | Date | What It Commemorates |\n|---------|------|---------------------|\n| **Human Rights Day** | 21 March | Remembers the Sharpeville Massacre (1960) |\n| **Freedom Day** | 27 April | Celebrates the first democratic election (1994) |\n| **Youth Day** | 16 June | Remembers the Soweto Uprising (1976) |\n| **Women\'s Day** | 9 August | Celebrates the 1956 Women\'s March to the Union Buildings |\n| **Heritage Day** | 24 September | Celebrates South Africa\'s diverse cultures |\n| **Day of Reconciliation** | 16 December | Promotes national unity and reconciliation |'),
  fb(8, 'The motto on South Africa\'s coat of arms, *!ke e: /xarra //ke*, means "___". Human Rights Day on 21 March remembers the ___ Massacre of 1960.',
    ['Diverse People Unite', 'Sharpeville'],
    'The motto comes from the /Xam language of the San people — one of South Africa\'s oldest nations. It means "Diverse People Unite," reflecting the ideal of a rainbow nation. The Sharpeville Massacre, where 69 peaceful protesters were killed by police, is remembered every year on Human Rights Day.'),
  q(9, 'Why does the South African national anthem include five different languages?',
    ['To represent the diversity of South Africa\'s people and the eleven official languages', 'Because the composer could not choose one language', 'Because each province has its own language', 'Because English was not allowed'], 0,
    'The national anthem is unique in the world because it includes five of South Africa\'s eleven official languages — isiXhosa, isiZulu, Sesotho, Afrikaans, and English. This reflects the idea that South Africa belongs to all its diverse peoples and that no one language or group is more important than another.'),
  t(10, '## Protecting Democracy Today\n\nDemocracy must be **protected** — it does not look after itself.\n\n### Threats to Democracy\n\n- **Corruption** — when leaders steal public money or abuse their power\n- **Voter apathy** — when people stop caring about voting\n- **Inequality** — when some people remain much poorer than others\n- **Xenophobia** — hatred and violence towards people from other countries\n- **Fake news** — false information that misleads people\n\n### Institutions That Protect Democracy\n\nThe Constitution created **Chapter 9 institutions** to guard democracy:\n\n| Institution | Role |\n|-------------|------|\n| **Public Protector** | Investigates complaints about government misconduct |\n| **South African Human Rights Commission** | Promotes and protects human rights |\n| **Commission for Gender Equality** | Promotes gender equality |\n| **Auditor-General** | Checks that government money is spent properly |\n| **Electoral Commission (IEC)** | Ensures free and fair elections |\n\nEvery South African has a role to play in protecting democracy — by voting, obeying the law, reporting corruption, and treating every person with dignity and respect.'),
];

// =============================================================================
// CHAPTER 2 (History – Term 1): An Ancient African Society — Kingdom of Mali
// =============================================================================

// --- Lesson 1: The Rise of Mali and Sundiata Keita ---
blockNum = 0;
const ch2_lesson1 = [
  t(1, '## West Africa Before Mali\n\nLong before Europeans arrived in Africa, great kingdoms and empires flourished in **West Africa**. The region between the **Sahara Desert** in the north and the tropical forests in the south was home to powerful civilisations.\n\n### The Ghana Empire (c. 300–1200)\n\n- The **Ghana Empire** (not the same as modern Ghana) was the first great West African empire\n- It was located in parts of present-day **Mauritania** and **Mali**\n- Ghana grew rich by controlling the **gold and salt trade** across the Sahara\n- Traders from North Africa brought **salt** south, and exchanged it for **gold** from West African mines\n- The king of Ghana taxed all goods that passed through his territory\n- Ghana declined due to **overgrazing**, **drought**, and attacks from the **Almoravids** (a Muslim Berber group)\n\n### Trans-Saharan Trade\n\nThe Sahara Desert was not an empty barrier — it was crossed by important **trade routes**:\n\n| From the North | From the South |\n|----------------|----------------|\n| Salt | Gold |\n| Cloth and textiles | Ivory |\n| Horses | Kola nuts |\n| Copper | Enslaved people |\n| Books | Leather goods |\n\n**Camels** made this trade possible. They could carry heavy loads and travel for days without water, earning them the name **"ships of the desert"**.'),
  q(2, 'Why was the Ghana Empire wealthy?',
    ['It controlled the gold and salt trade routes and taxed all goods passing through its territory', 'It had the largest army in the world', 'It traded with China by sea', 'It had diamond mines'], 0,
    'Ghana\'s wealth came from controlling the trade routes between the gold-producing regions of West Africa and the salt-producing regions of the Sahara. The king taxed every load of gold, salt, and other goods that entered or left the empire.'),
  t(3, '## Sundiata Keita — The Lion King of Mali\n\nThe **Kingdom of Mali** was founded by **Sundiata Keita** around **1235**. His story is one of the most famous in African history.\n\n### Sundiata\'s Story\n\n- Sundiata was a prince of the **Mandinka** people\n- As a child, he was **disabled** and could not walk — people mocked him and his mother\n- Despite his disability, he grew strong and became a great warrior and leader\n- The cruel king **Sumanguru Kante** of the Sosso people had conquered the Mandinka and killed many of Sundiata\'s brothers\n- Sundiata gathered an army and defeated Sumanguru at the **Battle of Kirina** in **1235**\n- After his victory, Sundiata united the Mandinka clans and neighbouring peoples into the **Mali Empire**\n\n### Sundiata\'s Achievements\n\n| Achievement | Detail |\n|-------------|--------|\n| **Founded Mali** | United many peoples into one powerful empire |\n| **Kouroukan Fouga** | Created a charter of laws (like a constitution) that organised society |\n| **Agriculture** | Encouraged farming, especially of crops like rice, sorghum, and cotton |\n| **Trade** | Controlled the gold mines and trade routes, making Mali very wealthy |\n| **Justice** | Established a system of fair laws and governance |\n\nSundiata is known as the **"Lion King"** of Mali. His story has been passed down through oral tradition by **griots** (storytellers and historians).'),
  fb(4, 'Sundiata Keita defeated the Sosso king Sumanguru Kante at the Battle of ___ in 1235. Sundiata\'s story has been preserved through oral tradition by storytellers called ___.',
    ['Kirina', 'griots'],
    'The Battle of Kirina in 1235 is the founding event of the Mali Empire. Griots are West African oral historians who memorise and recite the histories, stories, and genealogies of their people. They are the "living libraries" of West Africa.'),
  t(5, '## Mansa Musa — The Golden Emperor\n\n**Mansa Musa** (ruled **1312–1337**) was the most famous ruler of Mali and is considered one of the **wealthiest people in history**.\n\n### Mansa Musa\'s Pilgrimage to Mecca (1324)\n\nAs a devout Muslim, Mansa Musa undertook the **hajj** (pilgrimage to Mecca). His journey amazed the world:\n\n| Detail | Description |\n|--------|-------------|\n| **Entourage** | 60 000 people travelled with him |\n| **Gold** | 80 camels each carried about 136 kg of gold dust |\n| **Route** | Across the Sahara Desert and through Egypt to Mecca |\n| **In Cairo** | He gave away so much gold that the price of gold dropped for 12 years |\n| **Return** | He brought back scholars, architects, and books |\n\n### Why Was Mansa Musa So Wealthy?\n\n- Mali controlled the **Wangara gold fields** — the largest source of gold in the medieval world\n- The empire taxed all **trade** passing through its territory\n- Mali controlled the **salt trade** from the Sahara\n- The empire had fertile farmland along the **Niger River**\n\n### Mansa Musa\'s Legacy\n\n- He made Mali famous across the **Islamic world** and **Europe**\n- He built the **Djinguereber Mosque** in Timbuktu, which still stands today\n- He turned Timbuktu into a **centre of learning**\n- Mali appeared on the **Catalan Atlas** (1375) — a European map that showed Mansa Musa holding a gold nugget'),
  q(6, 'What happened when Mansa Musa passed through Cairo during his pilgrimage?',
    ['He gave away so much gold that the price of gold in Cairo dropped and did not recover for 12 years', 'He conquered Egypt and added it to his empire', 'He bought all the goods in Cairo\'s markets', 'He stayed for five years studying at a university'], 0,
    'Mansa Musa was so generous in Cairo that he flooded the economy with gold. There was suddenly so much gold available that its value crashed — it took about 12 years for the gold market to recover. This shows just how incredibly wealthy the Mali Empire was.'),
  t(7, '## Trade in Gold and Salt\n\nThe wealth of the Mali Empire was built on the trade of two key goods: **gold** and **salt**.\n\n### Gold\n\n- Mali controlled the **Wangara gold fields** (in the Bambuk and Bure regions)\n- Gold was mined by local people and traded northward\n- It was used for **coins, jewellery, and decoration** across the Islamic world and Europe\n- Mali was the world\'s **biggest supplier of gold** during the 14th century\n\n### Salt\n\n- Salt was mined at **Taghaza** in the Sahara Desert\n- Workers cut salt into large **blocks** that were loaded onto camels\n- In the hot climate of West Africa, salt was **essential** for health and preserving food\n- Salt was so valuable that in some places it was traded for **equal weights of gold**\n\n### How the Trade Worked — "Silent Barter"\n\nIn some areas, gold and salt were traded using **silent barter** (also called dumb barter):\n\n1. Salt traders left their salt at an agreed place and retreated\n2. Gold miners came, left gold next to the salt, and retreated\n3. Salt traders returned — if enough gold was offered, they took it and left the salt\n4. If not enough, they retreated again and waited for more gold\n5. This continued until both sides were satisfied\n\nThis system worked because the two groups **did not share a language** but could still trade fairly.'),
  fb(8, 'Salt was mined at ___ in the Sahara Desert. In some areas, gold and salt were exchanged through a system called silent ___.',
    ['Taghaza', 'barter'],
    'Taghaza was a harsh mining settlement deep in the Sahara where workers cut blocks of salt for the trans-Saharan trade. Silent barter (or dumb barter) was a clever system that allowed people who did not speak the same language to trade fairly without ever meeting face to face.'),
  q(9, 'Why was salt so valuable in West Africa?',
    ['People needed salt to stay healthy in the hot climate and to preserve food before refrigeration existed', 'Salt was used to build houses', 'Salt was only used as decoration', 'Salt was not actually valuable — gold was the only important trade good'], 0,
    'In the hot climate of West Africa, people lost salt through sweating and needed to replace it to stay healthy. Salt was also the only way to preserve meat and fish before refrigeration was invented. These needs made salt as precious as gold in many markets.'),
  t(10, '## The Importance of Oral Tradition\n\nMuch of what we know about ancient Mali comes from **oral tradition** — stories and histories passed down by word of mouth from generation to generation.\n\n### Griots — The Living Libraries\n\n- **Griots** (also called *jeli*) are professional storytellers, musicians, and historians in West Africa\n- They memorise the histories, genealogies, and stories of their people\n- A griot trains for **many years**, learning from an older griot\n- Griots performed at royal courts, advising kings and recording events\n- The **Epic of Sundiata** — the story of Mali\'s founding — was preserved by griots for centuries before being written down\n\n### Oral vs Written Sources\n\n| Oral Sources | Written Sources |\n|--------------|------------------|\n| Passed down by griots and elders | Recorded on paper or parchment |\n| Can change over time as stories are retold | Remain the same once written |\n| Rich in detail and cultural meaning | May reflect the writer\'s bias |\n| Difficult to date exactly | Can often be dated precisely |\n\nHistorians use **both** oral and written sources to piece together the history of Mali. Neither type is perfect on its own, but together they give us a fuller picture of the past.'),
];

// --- Lesson 2: Timbuktu as a Centre of Learning ---
blockNum = 0;
const ch2_lesson2 = [
  t(1, '## The City of Timbuktu\n\n**Timbuktu** was one of the most important cities in the Mali Empire and in all of Africa. Founded around **1100** by Tuareg nomads, it grew into a great centre of **trade** and **learning**.\n\n### Location\n\n- Timbuktu is located near the **Niger River** on the southern edge of the **Sahara Desert**\n- This position made it the **meeting point** for traders from North Africa (bringing salt) and West Africa (bringing gold)\n- The Niger River provided water, fertile farmland, and a route for transporting goods by boat\n\n### Timbuktu as a Trading Centre\n\n| Goods from the North | Goods from the South |\n|---------------------|---------------------|\n| Salt | Gold |\n| Cloth | Ivory |\n| Horses | Kola nuts |\n| Copper | Leather |\n| Books and paper | Enslaved people |\n\nAt its height in the **14th and 15th centuries**, Timbuktu had a population of about **100 000 people** — a major city by any standard.'),
  q(2, 'Why was Timbuktu\'s location important for trade?',
    ['It was at the meeting point of the Sahara Desert and the Niger River, connecting northern and southern trade routes', 'It was on the coast next to the Atlantic Ocean', 'It was in the middle of a gold mine', 'It was close to Europe'], 0,
    'Timbuktu\'s position on the edge of the Sahara and near the Niger River made it the perfect place for North African and West African traders to meet and exchange goods. This location turned it into one of the wealthiest cities in the medieval world.'),
  t(3, '## Timbuktu as a Centre of Learning\n\nTimbuktu was not only a trading city — it became one of the **greatest centres of learning** in the medieval world.\n\n### The University of Sankore\n\n- The **Sankore Mosque** was the heart of learning in Timbuktu\n- At its peak, it had up to **25 000 students**\n- Scholars came from across the Islamic world to study and teach\n- Students studied for many years to earn their qualifications\n\n### What Was Studied?\n\n| Subject | Description |\n|---------|-------------|\n| **Islamic theology** | Study of the Quran and religious law |\n| **Mathematics** | Arithmetic, algebra, and geometry |\n| **Astronomy** | Study of the stars and planets |\n| **Medicine** | Healing practices and herbal remedies |\n| **History** | Records of events and peoples |\n| **Law** | Islamic law and systems of justice |\n| **Geography** | Knowledge of lands and trade routes |\n\n### Three Great Mosques\n\nTimbuktu had three famous mosques that served as centres of worship and learning:\n1. **Djinguereber Mosque** — built by Mansa Musa after his return from Mecca\n2. **Sankore Mosque** — the great university\n3. **Sidi Yahia Mosque** — built around 1400'),
  fb(4, 'The ___ Mosque was the great university in Timbuktu, with up to 25 000 students at its peak. The Djinguereber Mosque was built by Mansa ___ after his pilgrimage to Mecca.',
    ['Sankore', 'Musa'],
    'The Sankore Mosque (University of Sankore) attracted scholars from across the Islamic world and offered education in subjects ranging from theology to astronomy. Mansa Musa built the Djinguereber Mosque using architects he brought back from his famous hajj.'),
  t(5, '## The Manuscripts of Timbuktu\n\nOne of Timbuktu\'s greatest treasures is its **manuscripts** — handwritten books and documents produced by scholars over many centuries.\n\n### What Are the Timbuktu Manuscripts?\n\n- Hundreds of thousands of manuscripts were written in **Arabic** and in local languages using Arabic script\n- They cover topics including **science, law, history, poetry, medicine, mathematics**, and **philosophy**\n- Some manuscripts are over **700 years old**\n- Many were kept in **private family libraries**, hidden from invaders and colonial powers\n\n### Why Are They Important?\n\n- They prove that Africa had a **long tradition of literacy and scholarship**\n- They challenge the false claim that Africa had **no written history**\n- They contain knowledge about **science, medicine, and law** that was advanced for its time\n- They show connections between West Africa and the wider **Islamic world**\n\n### Preserving the Manuscripts\n\n- In **2003**, South Africa and Mali launched the **Timbuktu Manuscripts Project** to preserve these documents\n- This was led by former President **Thabo Mbeki**\n- When conflict threatened Timbuktu in **2012–2013**, brave librarians **smuggled thousands of manuscripts** to safety in southern Mali\n- Today, organisations are working to **digitise** (scan and store electronically) the manuscripts so they can be studied by scholars worldwide'),
  q(6, 'Why are the Timbuktu manuscripts historically important?',
    ['They prove that Africa had a long tradition of literacy, scholarship, and written history', 'They contain recipes for cooking', 'They were written by European explorers', 'They are only about religion and have no scientific content'], 0,
    'The Timbuktu manuscripts are living proof that Africa had sophisticated centres of learning and a rich written tradition centuries before European colonisation. They cover science, medicine, law, and many other subjects, showing the depth of African intellectual achievement.'),
  t(7, '## The Spread of Islam in West Africa\n\n**Islam** played a major role in shaping the Mali Empire and connecting it to the wider world.\n\n### How Islam Reached West Africa\n\n- Muslim **traders from North Africa** brought Islam across the Sahara along the trade routes\n- Trade and religion were closely linked — Muslim merchants preferred trading with fellow Muslims\n- Mali\'s rulers adopted Islam because it connected them to the wealthy **Islamic trading network**\n- Islam brought **literacy** (through Arabic), **law** (Sharia), and **education** to the empire\n\n### Islam and Traditional Beliefs\n\n- Many ordinary people in Mali practised a **blend** of Islam and traditional African religions\n- Rulers were publicly Muslim, but traditional beliefs in **ancestors** and **nature spirits** continued\n- This blending of different religious practices is called **syncretism**\n\n### The Importance of Arabic\n\n- The **Arabic language** allowed Mali to keep **written records** of trade, law, and history\n- Scholars wrote manuscripts in Arabic, creating the intellectual tradition of Timbuktu\n- Arabic connected Mali to the vast world of **Islamic scholarship** stretching from Spain to China'),
  fb(8, 'Muslim traders brought Islam to West Africa along the trans-Saharan trade routes. The blending of Islam with traditional African religions is known as ___.',
    ['syncretism'],
    'Syncretism is the mixing of different religious or cultural practices. In West Africa, many people combined Islamic worship with traditional beliefs about ancestors and nature spirits. This was common throughout the history of Islam in the region.'),
  q(9, 'How did Islam benefit the rulers of the Mali Empire?',
    ['It connected them to the Islamic trading network, provided written laws, brought literacy through Arabic, and gave diplomatic prestige', 'It forced them to give up all their power', 'It had no benefits for the rulers', 'It made them stop trading with North Africa'], 0,
    'Islam was strategically valuable to Mali\'s rulers. It connected them to a vast trade network, gave them access to written Arabic for record-keeping and diplomacy, provided a legal framework (Sharia law), and brought international prestige.'),
  t(10, '## The Decline of Mali and Its Legacy\n\n### Why Did Mali Decline?\n\n| Factor | Explanation |\n|--------|-------------|\n| **Weak rulers** | After Mansa Musa, some later emperors were less capable leaders |\n| **Power struggles** | Disputes over who should be the next Mansa weakened the empire |\n| **Rebellions** | Provinces on the edges of the empire broke away |\n| **Rise of Songhai** | The **Songhai Empire**, based at Gao, grew more powerful and eventually conquered Mali |\n| **Changing trade routes** | New trade routes bypassed Mali |\n\n### The Legacy of Mali\n\nThe Mali Empire left a lasting legacy:\n\n- It showed that **African civilisations** were wealthy, powerful, and sophisticated\n- Timbuktu\'s **scholarly tradition** proved that Africa had a rich intellectual history\n- The **manuscripts** of Timbuktu are still being studied and preserved today\n- The **Epic of Sundiata** is one of the great stories of world literature\n- The **trans-Saharan trade** connected Africa to the global economy centuries before European colonisation\n- Mali\'s system of **governance and law** (the Kouroukan Fouga) is one of the earliest examples of a constitution\n\n### Connecting Past and Present\n\nThe modern country of **Mali** is named after the ancient empire. Many West African people today are proud of their connection to this great civilisation. Studying Mali helps us understand that Africa\'s history is rich, complex, and worthy of respect.'),
];

